        "掌握相似三角形的定义：对应角相等、对应边成比例",
        "知道相似比的含义，写相似式时字母一一对应",
        "会用 AA 判定两个三角形相似，并会找相等的角",
        "知道另外两条判定：两边成比例且夹角相等、三边成比例",
        "记住性质：对应线段比与周长比等于相似比，面积比等于相似比的平方",
