LESSONS.append({
    "id": "hanshu-lingdian",
    "file": "lesson-hanshu-lingdian.html",
    "stage": "gaozhong",
    "grade": "高一",
    "title": "函数的零点",
    "subtitle": "方程 f(x) = 0 的根",
    "brief": "函数图像穿过 x 轴的地方，横坐标就是零点，它其实是一个数，不是坐标点。零点就是方程 f(x) = 0 的实根，也是两个图像交点问题。判断零点存在用零点存在定理：图像连续不断、两端函数值一正一负，中间至少有一个零点。定理只说「有」，不保证「只有一个」。",
    "minutes": 8,
    "difficulty": 3,
    "tags": ["零点", "零点存在定理", "二分法", "方程根"],
    "video": "assets/videos/hanshu-lingdian.mp4",
    "videoNote": "先让图像穿过 x 轴，标出零点的位置，再用端点异号引出零点存在定理，最后演示二分法怎样一步步逼近零点。",
    "keyformula": "异号就必有零点",
    "goals": [
        "理解零点的定义，知道零点是数不是点",
        "掌握零点存在定理的条件与结论",
        "会把零点问题转化为两个图像的交点",
        "了解二分法求近似零点的步骤",
        "知道零点与不等式解集的关系",
    ],
    "chapters": [
        "图像穿过 x 轴的地方",
        "零点的定义",
        "零点存在定理",
        "零点个数怎么看",
        "二分法",
        "零点与不等式",
        "异号就必有零点",
    ],
    "knowledge": [
        {
            "kind": "concept",
            "title": "什么是零点",
            "body": [
                "使 f(x) = 0 成立的实数 x，叫函数 y = f(x) 的零点。",
                "图像上，零点就是曲线与 x 轴交点的横坐标。",
                "零点是一个数，不是点，所以不能写成 (3, 0)。",
                "求零点就是解方程，方程的实根有几个，零点就有几个。",
            ],
            "formula": "f(x) = 0",
        },
        {
            "kind": "formula",
            "title": "零点存在定理",
            "body": [
                "如果函数 f(x) 在闭区间 [a, b] 上的图像连续不断，并且 f(a) · f(b) < 0，那么 f(x) 在 (a, b) 内至少有一个零点。",
                "「连续」是说图像中间不能断，「异号」是说两端一个在 x 轴上方、一个在下方。",
                "两个条件缺一不可：不连续时可能断开，同号时可能整段都在一侧。",
                "定理只保证存在，不保证唯一；要证明唯一，还要加上单调性。",
            ],
            "formula": "f(a) · f(b) < 0",
        },
        {
            "kind": "concept",
            "title": "零点个数怎么看",
            "body": [
                "把 f(x) = 0 变形为 g(x) = h(x)，方程的解就是两个图像交点的横坐标。",
                "交点有几个，零点就有几个，这比硬解方程直观。",
                "如果 f 在区间上单调，并且两端异号，那么零点恰好只有一个。",
                "遇到含参数的零点个数问题，通常是让图像上下平移，看交点数怎么变。",
            ],
            "formula": "f(x) = 0 ⇔ g(x) = h(x)",
        },
        {
            "kind": "example",
            "title": "二分法",
            "body": [
                "已知 f(a) · f(b) < 0，取中点 c = (a + b) / 2，算 f(c)。",
                "若 f(c) = 0，c 就是零点；若 f(a) · f(c) < 0，零点在 (a, c)；否则在 (c, b)。",
                "每次把范围缩小一半，重复到区间长度小于要求的精度。",
                "二分法只适用于连续且端点异号的情况，求的是近似值。",
            ],
            "formula": "c = (a + b) / 2",
        },
        {
            "kind": "concept",
            "title": "零点与不等式",
            "body": [
                "函数的零点把定义域分成几段，在每一段里函数值的符号通常不变。",
                "所以解 f(x) > 0 或 f(x) < 0，先求零点，再判断各段的符号。",
                "这就是「穿根法」的依据：零点处穿过去，符号就翻一次。",
                "重根处不穿过去，符号不变，这是最容易出错的地方。",
            ],
            "formula": "先求零点，再定符号",
        },
    ],
    "pitfalls": [
        "零点不是点：答案写 x = 3，不能写成 (3, 0)。",
        "定理只保证存在，不能直接说「有且只有一个」。",
        "图像不连续时定理不成立，用之前先确认连续性。",
        "两端同号也可能有零点，比如两个零点都在区间内。",
    ],
    "summary": "函数的零点就是方程 f(x) = 0 的实根，也是图像与 x 轴交点的横坐标，它是一个数。零点存在定理：f 在 [a, b] 上连续且 f(a) · f(b) < 0，则 (a, b) 内至少有一个零点；加上单调性才能保证唯一。求零点个数可以转化为两个图像的交点个数，近似解用二分法，解不等式则先求零点再判断各段符号。",
    "questions": [
        {
            "prompt": "函数 f(x) = x − 3 的零点是什么？",
            "options": ["−3", "3", "(3, 0)"],
            "answer": 1,
            "explanation": "令 x − 3 = 0 得 x = 3。零点是数，不能写成坐标 (3, 0)。",
        },
        {
            "prompt": "f(x) 在 [1, 2] 上连续，f(1) = −1，f(2) = 2，可以得出什么结论？",
            "options": ["(1, 2) 内一定有零点", "零点个数一定是 1", "无法判断"],
            "answer": 0,
            "explanation": "连续且两端异号，由零点存在定理可知 (1, 2) 内至少有一个零点。",
        },
        {
            "prompt": "二分法每一步做的事情是什么？",
            "options": ["直接求出精确根", "画出函数图像", "取中点并判断符号"],
            "answer": 2,
            "explanation": "二分法取区间中点，算函数值，根据符号把范围缩小一半，逐步逼近零点。",
        },
        {
            "prompt": "若 f(a) · f(b) > 0，能否断定区间内没有零点？",
            "options": ["能，一定没有", "不能，可能有偶数个零点", "不能，一定有零点"],
            "answer": 1,
            "explanation": "两端同号时，图像可能在区间内上下穿过 x 轴两次，所以不能断定没有零点。",
        },
    ],
})

